153	func (h *DVEHandlers) GetDVENodeTasksAlias(w http.ResponseWriter, r *http.Request) {
154		vars := mux.Vars(r)
155		nodeID := vars["nodeId"]
156	
157		if h.dveManager == nil {
158			w.Header().Set("Content-Type", "application/json")
159			json.NewEncoder(w).Encode(map[string]interface{}{
160				"node_id":   nodeID,
161				"tasks":     []interface{}{},
162				"total":     0,
163				"timestamp": getCurrentTimestamp(),
164			})
165			return
166		}
167	
168		tasks, err := h.dveManager.GetNodeTasks(nodeID)
169		if err != nil {
170			w.Header().Set("Content-Type", "application/json")
171			w.WriteHeader(http.StatusInternalServerError)
172			json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
173			return
174		}
175	
176		if tasks == nil {
177			tasks = []*objects.ValidationTask{}
178		}
179	
180		w.Header().Set("Content-Type", "application/json")
181		json.NewEncoder(w).Encode(map[string]interface{}{
182			"node_id": nodeID,
183			"tasks":   tasks,
184			"total":   len(tasks),
185		})
186	}
187	
188	// GetDVENodeMetricsAlias handles GET /api/dve/{nodeId}/metrics (alias for monitor-panel compatibility)
189	func (h *DVEHandlers) GetDVENodeMetricsAlias(w http.ResponseWriter, r *http.Request) {
190		vars := mux.Vars(r)
191		nodeID := vars["nodeId"]
192	
193		if h.dveManager == nil {
194			w.Header().Set("Content-Type", "application/json")
195			json.NewEncoder(w).Encode(map[string]interface{}{
196				"node_id":   nodeID,
197				"metrics":   map[string]interface{}{},
198				"timestamp": getCurrentTimestamp(),
199			})
200			return
201		}
202	
203		metrics, err := h.dveManager.GetNodeMetrics(nodeID)
204		if err != nil {
205			w.Header().Set("Content-Type", "application/json")
206			w.WriteHeader(http.StatusNotFound)
207			json.NewEncoder(w).Encode(map[string]string{"error": err.Error()})
208			return
209		}
210	
211		metrics["timestamp"] = getCurrentTimestamp()
212	
213		w.Header().Set("Content-Type", "application/json")
214		json.NewEncoder(w).Encode(metrics)
215	}
216	
217	// GetP2PPeers handles GET /api/p2p/peers — returns connected P2P peer list from P2PManager
218	func (h *DVEHandlers) GetP2PPeers(w http.ResponseWriter, r *http.Request) {
219		type PeerEntry struct {
220			ID      string `json:"id"`
221			Address string `json:"address"`
222			Role    string `json:"role"`
223			Status  string `json:"status"`
224			Latency int64  `json:"latency_ms"`
225		}
226	
227		peers := make([]PeerEntry, 0)
228	
229		if h.dveManager != nil {
230			rawPeers := h.dveManager.GetConnectedP2PPeers()
231			for _, p := range rawPeers {
232				status := p.Status
233				if status == "" {
234					status = "connected"
235				}
236				peers = append(peers, PeerEntry{
237					ID:      p.ID,
238					Address: p.Address,
239					Role:    p.Role,
240					Status:  status,
241					Latency: p.Latency,
242				})
243			}
244		}
245	
246		w.Header().Set("Content-Type", "application/json")
247		json.NewEncoder(w).Encode(map[string]interface{}{
248			"peers":     peers,
249			"total":     len(peers),
250			"timestamp": getCurrentTimestamp(),
251		})
252	}
253	
254	// PostAgentResponse handles POST /api/v1/dve/{nodeId}/agent/response
255	func (h *DVEHandlers) PostAgentResponse(w http.ResponseWriter, r *http.Request) {
256		vars := mux.Vars(r)
257		nodeID := vars["nodeId"]
258	
259		var req struct {
260			Message string `json:"message"`
261		}
262		if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
263			w.WriteHeader(http.StatusBadRequest)
264			return
265		}
266	
267		if h.agentService != nil {
268			// Use an interface assertion or just call it if we know the type
269			type broadcaster interface {
270				BroadcastAgentMessage(dveID string, message string)
271			}
272			if b, ok := h.agentService.(broadcaster); ok {
273				b.BroadcastAgentMessage(nodeID, req.Message)
274			}
275		}
276	
277		w.WriteHeader(http.StatusOK)
278	}
