		json.NewEncoder(w).Encode(map[string]interface{}{
			"node_id":   nodeID,
			"metrics":   map[string]interface{}{},
			"timestamp": getCurrentTimestamp(),
		})
		return
	}

	metrics, err := h.dveManager.GetNodeMetrics(nodeID)
	if err != nil {
		w.Header().Set("Content-Type", "application/json")
