	response := DVENodeResponse{
		Success:   true,
		Data:      nodes,
		Total:     len(nodes),
		Timestamp: getCurrentTimestamp(),
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(response)
}

