		container, err := dcs.containerOrchestrator.ProvisionContainer(creation.ID)
		if err != nil {
			log.Printf("[DVE Creation] Error provisioning container for %s: %v", creation.ID, err)
			dcs.updateCreationStatus(creation.ID, "failed")
